"""Refresh the existing acceptance report with scoped Chrome recovery proof."""
from pathlib import Path
import datetime,html,json,re,shutil
root=Path(__file__).parent/'evidence/chrome-recovery-20261020';logs=root/'logs';logs.mkdir(exist_ok=True)
load=lambda name:json.loads((root/name).read_text(encoding='utf-8'))
for name,target in [('recovery-service-final.log','service.log'),('recovery-release-d.log','release.log'),('recovery-docs-build.log','docs-build.log')]:shutil.copyfile(Path(__file__).parent.parent/'.local'/name,logs/target)
assert '# pass 429' in (logs/'service.log').read_text() and '# fail 0' in (logs/'service.log').read_text()
shutil.copytree(root.parent/'immediate-phase-20261019/recovery-workflow-regression',root/'workflow',dirs_exist_ok=True)
cohorts=[dict(name='Service regression, including interruption and strict checker retry',passed=429,path='logs/service.log')]
for name,count,title in [('workspace-final-ui',22,'Workspace regression: checker error, presentation, real socket loss and explicit task end'),('goals-final-ui',8,'Existing goal continuity/reviews and workflow-context regression'),('peers-final-ui',4,'Cross-tab SDK/DOM/WebSocket fill and Save regression'),('workflow',1,'Three-form workflow Save/readback — synthetic model and policy adapter'),('live-final-d',5,'Actual-model local Customer → Note → public MCP acceptance'),('scope-ui-final',1,'Actual-model current-page scope notice and complete-request transfer'),('user-chrome-verification.json',3,'Existing user Chrome guidance, browser minimize/restore and restore/maximize')]:
 data=load(name if name.endswith('.json') else name+'/results.json');assert len(data['results'])==count and all(r['status']=='passed' for r in data['results']),name
 cohorts.append(dict(name=title,passed=count,path=name if name.endswith('.json') else name+'/results.json'))
assert load('real-checker-recovery.json')['status']=='passed';cohorts.append(dict(name='Real provider truncation → one compact verdict retry, unchanged global setting',passed=1,path='real-checker-recovery.json'))
passed=sum(c['passed'] for c in cohorts)
report=dict(at=datetime.datetime.now(datetime.timezone.utc).isoformat(),release='20261020-recovery-d',gatewayRelease='20261020-recovery-c-gateway',passed=passed,failed=0,partial=0,passRate=100,cohorts=cohorts,scope='Current Chrome/chat/checker/scope-recovery update; not full Phase 1/2 certification',limitations=['Earlier unarchived transcript was not recovered. The continuation was reconstructed from the observed synthetic draft.','Actual user Chrome checks were read-only guidance and window retention. Cross-tab fill/save acceptance used a separate explicitly authorized Chrome test profile.','The current-page scope notice is an explicit UI boundary and transition, not a claim of perfect semantic automatic goal routing.','The real retry probe used a temporary per-call 128-token cap to force truncation; global maker/checker remained enabled on the same passive route at 2048.','Native Safari/iOS, Android Chrome and full screen-reader checks remain previously deferred. Existing registrations do not establish fresh-owner DNS/email acceptance.','Earlier failures and test-harness readiness failures remain available; a successful final run does not prove statistical model reliability.'])
(root/'report.json').write_text(json.dumps(report,indent=2),encoding='utf-8')
base='../chrome-recovery-20261020/';esc=html.escape
section=f'''<section class="card" id="chrome-recovery"><small>Latest update · {report['release']}</small><h1>Chrome conversation and checker recovery</h1><p class="score">{passed}/{passed} current checks passed · 100%</p><p>0 failed · 0 partial. The counts below describe this scoped update. Earlier report sections overlap these regressions and must not be added together. This does not certify the previously deferred device/accessibility matrix or full Phase 1/2.</p><p><strong>Verified in the user’s existing Chrome:</strong> read-only MCP guidance completed, and both browser minimize/restore and restore/maximize retained the prompt and response. The local draft was reloaded for the fix and restored to the same three synthetic values without Save. Its existing MCP counterpart is online; Goal plan is selected, and a reconstructed continuation prompt is prepared but unsent.</p><div class="scroll"><table><tr><th>Current test cohort</th><th>Passed</th><th>Evidence</th></tr>'''
for c in cohorts:section+=f'<tr><td>{esc(c["name"])}</td><td>{c["passed"]}</td><td><a href="{base+c["path"]}">Results</a></td></tr>'
section+='''</table></div><h2>Findings, fixes and recommendations</h2><div class="scroll"><table><tr><th>Finding</th><th>Fix / result</th><th>Recommendation</th></tr><tr><td>A socket close was treated as End task, even with no task</td><td>Transport interruption is separate. Retain historical messages, invalidate private pending work, never replay effects. Explicit End task still clears private access.</td><td>Refresh old SDK instances when safe; reconnect never implies a pending Save should be repeated.</td></tr><tr><td>The passive checker exhausted its budget without a usable verdict</td><td>Recognize incomplete cloud output. One existing bounded retry may use the supported provider’s compact JSON mode. Same checker, same token cap/deadline, strict all-pass verdict and normal action approvals.</td><td>Keep monitoring latency and provider quality; unknown/incomplete verdicts still stop execution.</td></tr><tr><td>A local field review was confused with a cross-website goal</td><td>Every current-page review identifies its scope. Plan complete task rejects the local-only review and preserves the full request in Goal plan without applying fields.</td><td>Use Goal plan for coordinated multi-tab work; review the ordered plan before starting.</td></tr><tr><td>Input could be available before copilot startup completed</td><td>Composer and Send stay disabled until configuration/history initialization completes.</td><td>Wait for Panel connected before beginning a task.</td></tr><tr><td>Recipient planning added redundant navigation</td><td>Generic maker/checker guidance now checks the already-observed form before adding navigation. The final actual-model multi-tab run passed.</td><td>A checker refusal is a safe stop, not completion; inspect the failed step rather than repeat earlier writes.</td></tr></table></div><p>The compact retry uses the provider’s documented <a href="https://api-docs.deepseek.com/guides/thinking_mode/">thinking-mode API toggle</a> only on a supported endpoint. It never treats reasoning text as a verdict, changes the selected model, disables maker/checker, or changes local-model thinking policy.</p><div class="grid">'''
images=[('Actual user Chrome: conversation retained after native minimize/restore and maximize','user-chrome-chat-after-minimize-maximize.png'),('Checker error plus presentation regression retained history','workspace-final-ui/UX22_CHECKER_FAILURE_AND_PRESENTATION_RETAIN_CHAT.png'),('Dropped sockets reconnect without losing historical chat or replaying effects','workspace-final-ui/UX20_DROPPED_WEBSOCKETS_RESTORE_PAIRING_WITHOUT_REFRESH_OR_REPLAY.png'),('Full request preserved in Goal plan without applying a local-only review','scope-ui-final/scope-guard-and-request-preserved.png'),('Actual-model source goal after local and recipient saves','live-final-d/LIVE_PEER02_ACTUAL_MODEL_CUSTOMER_TO_NOTE_GOAL_AND_TWO_SAVES-source.png'),('Public recipient used the shared form value without public submission','live-final-d/LIVE_PEER04_PRIVATE_FORM_VALUES_DRIVE_PUBLIC_INCOMING_GOAL-public.png')]
for caption,path in images:
 assert (root/path).is_file(),path
 section+=f'<figure><a href="{base+path}"><img loading="lazy" src="{base+path}" alt="{esc(caption)}"></a><figcaption>{esc(caption)}</figcaption></figure>'
section+='</div><h2>Operational proof and limits</h2><ul>'
for title,path in [('Current machine-readable report','report.json'),('Deployed source hashes and unchanged global checker policy','runtime-verification.json'),('Deployment health and preserved workers/platform','deployment.json'),('Provider source lineage before the adapter patch','provider-lineage.json'),('Linux regression log — not counted twice','logs/linux-tests.log'),('Help publication and exact retrieval verification','logs/release.log'),('Documentation build','logs/docs-build.log')]:section+=f'<li><a href="{base+path}">{title}</a></li>'
section+='</ul><ul>'+''.join('<li>'+esc(item)+'</li>' for item in report['limitations'])+'</ul><details><summary>Earlier attempts retained</summary><ul>'
for path in sorted(root.glob('*/results.json')):
 if path.parent.name not in ['workspace-final-ui','goals-final-ui','peers-final-ui','workflow','live-final-d','scope-ui-final']:section+=f'<li><a href="{base+path.relative_to(root).as_posix()}">{esc(path.parent.name)}</a></li>'
section+='</ul></details></section>'
for file in [root.parent/'goal-plans-20261020/index.html',root.parent/'pointer-overlay-20261020/index.html']:
 text=file.read_text(encoding='utf-8')
 if 'id="chrome-recovery"' in text:text,n=re.subn(r'<section class="card" id="chrome-recovery">.*?</section>',lambda _:section,text,count=1,flags=re.S);assert n==1
 else:text=text.replace('<main>','<main>'+section,1)
 file.write_text(text,encoding='utf-8')
print(json.dumps(dict(passed=passed,failed=0,partial=0,passRate=100)))
